CREATE TYPE "StudentAcademicStatus" AS ENUM ('ACTIVE','DEFERRED','SUSPENDED','COMPLETED');
CREATE TYPE "StudentSimulationProfile" AS ENUM ('MICRO_PAYMENT_HARDSHIP','EXAM_PERIOD_DISTRESS','AID_GAP_RELIANCE','CHRONIC_HIGH_BALANCE','STABLE_LUMP_SUM_CONTROL','MIXED_CONTROL');
CREATE TYPE "StudentFinancialStatus" AS ENUM ('CLEARED','PARTIALLY_PAID','OVERDUE','BLOCKED');
CREATE TYPE "StudentPaymentSource" AS ENUM ('FAMILY','SELF','HELB','SCHOLARSHIP','NGO','UNIVERSITY_WAIVER');
CREATE TYPE "StudentAidType" AS ENUM ('HELB','GOVERNMENT_SCHOLARSHIP','PRIVATE_SCHOLARSHIP','NGO_SPONSORSHIP','UNIVERSITY_WAIVER');
CREATE TYPE "StudentAidStatus" AS ENUM ('EXPECTED','PARTIALLY_DISBURSED','DISBURSED','CANCELLED');
CREATE TYPE "StudentFinanceBlockType" AS ENUM ('EXAM_CLEARANCE','REGISTRATION','RESULTS_WITHHELD','PORTAL_RESTRICTION');
CREATE TYPE "StudentAssistanceType" AS ENUM ('TUITION','UPKEEP','GOODS');
CREATE TABLE "students" ("id" UUID NOT NULL,"userId" UUID,"registrationNumber" TEXT NOT NULL,"fullName" TEXT NOT NULL,"programme" TEXT NOT NULL,"school" TEXT NOT NULL,"yearOfStudy" INTEGER NOT NULL,"academicStatus" "StudentAcademicStatus" NOT NULL DEFAULT 'ACTIVE',"simulationProfile" "StudentSimulationProfile" NOT NULL,"admittedAt" TIMESTAMP(3) NOT NULL,"expectedGraduation" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "students_pkey" PRIMARY KEY ("id"));
CREATE TABLE "academic_semesters" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"academicYear" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"feeDueAt" TIMESTAMP(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "academic_semesters_pkey" PRIMARY KEY ("id"));
CREATE TABLE "student_financial_records" ("id" UUID NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"invoicedAmount" DECIMAL(18,2) NOT NULL,"paidAmount" DECIMAL(18,2) NOT NULL,"aidAmount" DECIMAL(18,2) NOT NULL DEFAULT 0,"outstandingBalance" DECIMAL(18,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'KES',"status" "StudentFinancialStatus" NOT NULL,"snapshotAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "student_financial_records_pkey" PRIMARY KEY ("id"));
CREATE TABLE "student_payments" ("id" UUID NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"reference" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"source" "StudentPaymentSource" NOT NULL,"paidAt" TIMESTAMP(3) NOT NULL,"description" TEXT,CONSTRAINT "student_payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam_calendars" ("id" UUID NOT NULL,"semesterId" UUID NOT NULL,"programme" TEXT,"examType" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"clearanceDeadline" TIMESTAMP(3) NOT NULL,CONSTRAINT "exam_calendars_pkey" PRIMARY KEY ("id"));
CREATE TABLE "student_aid_records" ("id" UUID NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"aidType" "StudentAidType" NOT NULL,"providerName" TEXT NOT NULL,"awardedAmount" DECIMAL(18,2) NOT NULL,"disbursedAmount" DECIMAL(18,2) NOT NULL,"status" "StudentAidStatus" NOT NULL,"reference" TEXT NOT NULL,"disbursedAt" TIMESTAMP(3),CONSTRAINT "student_aid_records_pkey" PRIMARY KEY ("id"));
CREATE TABLE "student_finance_blocks" ("id" UUID NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"blockType" "StudentFinanceBlockType" NOT NULL,"reason" TEXT NOT NULL,"blockedAt" TIMESTAMP(3) NOT NULL,"resolvedAt" TIMESTAMP(3),CONSTRAINT "student_finance_blocks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "student_assistance_history" ("id" UUID NOT NULL,"studentId" UUID NOT NULL,"semesterId" UUID NOT NULL,"assistanceType" "StudentAssistanceType" NOT NULL,"providerName" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"reference" TEXT NOT NULL,"providedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "student_assistance_history_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "students_userId_key" ON "students"("userId"); CREATE UNIQUE INDEX "students_registrationNumber_key" ON "students"("registrationNumber"); CREATE INDEX "students_academicStatus_programme_idx" ON "students"("academicStatus","programme"); CREATE INDEX "students_simulationProfile_idx" ON "students"("simulationProfile");
CREATE UNIQUE INDEX "academic_semesters_code_key" ON "academic_semesters"("code"); CREATE INDEX "academic_semesters_active_startsAt_idx" ON "academic_semesters"("active","startsAt");
CREATE INDEX "student_financial_records_semesterId_status_idx" ON "student_financial_records"("semesterId","status"); CREATE UNIQUE INDEX "student_financial_records_studentId_semesterId_key" ON "student_financial_records"("studentId","semesterId");
CREATE UNIQUE INDEX "student_payments_reference_key" ON "student_payments"("reference"); CREATE INDEX "student_payments_studentId_paidAt_idx" ON "student_payments"("studentId","paidAt"); CREATE INDEX "student_payments_semesterId_source_idx" ON "student_payments"("semesterId","source");
CREATE INDEX "exam_calendars_startsAt_endsAt_idx" ON "exam_calendars"("startsAt","endsAt"); CREATE UNIQUE INDEX "exam_calendars_semesterId_programme_examType_key" ON "exam_calendars"("semesterId","programme","examType");
CREATE UNIQUE INDEX "student_aid_records_reference_key" ON "student_aid_records"("reference"); CREATE INDEX "student_aid_records_studentId_semesterId_idx" ON "student_aid_records"("studentId","semesterId"); CREATE INDEX "student_aid_records_aidType_status_idx" ON "student_aid_records"("aidType","status");
CREATE INDEX "student_finance_blocks_studentId_blockedAt_idx" ON "student_finance_blocks"("studentId","blockedAt"); CREATE INDEX "student_finance_blocks_semesterId_blockType_idx" ON "student_finance_blocks"("semesterId","blockType");
CREATE UNIQUE INDEX "student_assistance_history_reference_key" ON "student_assistance_history"("reference"); CREATE INDEX "student_assistance_history_studentId_providedAt_idx" ON "student_assistance_history"("studentId","providedAt");
ALTER TABLE "students" ADD CONSTRAINT "students_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "student_financial_records" ADD CONSTRAINT "student_financial_records_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "student_financial_records" ADD CONSTRAINT "student_financial_records_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "student_payments" ADD CONSTRAINT "student_payments_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "student_payments" ADD CONSTRAINT "student_payments_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_calendars" ADD CONSTRAINT "exam_calendars_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "student_aid_records" ADD CONSTRAINT "student_aid_records_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "student_aid_records" ADD CONSTRAINT "student_aid_records_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "student_finance_blocks" ADD CONSTRAINT "student_finance_blocks_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "student_finance_blocks" ADD CONSTRAINT "student_finance_blocks_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "student_assistance_history" ADD CONSTRAINT "student_assistance_history_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "students"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "student_assistance_history" ADD CONSTRAINT "student_assistance_history_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "academic_semesters"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
